// stores/cart.ts
import { defineStore } from 'pinia'

export interface CartItem {
  id: string
  name: string
  price: number
  quantity: number
}

export const useCartStore = defineStore('cart', {
  state: () => ({
    items: [] as CartItem[],
  }),

  getters: {
    total(state): number {
      return state.items.reduce((sum, item) => sum + item.price * item.quantity, 0)
    },
  },

  actions: {
    addItem(item: Omit<CartItem, 'quantity'>, quantity = 1) {
      const existing = this.items.find((i) => i.id === item.id)
      if (existing) {
        existing.quantity += quantity
      } else {
        this.items.push({ ...item, quantity })
      }
    },

    removeItem(id: string) {
      const index = this.items.findIndex((i) => i.id === id)
      if (index !== -1) {
        this.items.splice(index, 1)
      }
    },
  },
})
```

This uses Pinia's Options-style `defineStore` (still fully Composition-API-friendly for consumers via `useCartStore()`). `addItem` merges quantities for duplicate IDs; `removeItem` deletes the item entirely. `total` is a getter computed from `items`.
